 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Nisha. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Nisha, I'm Emily Wilson. I'm calling because my current data plan is way too small for my needs and my phone has been acting up lately.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that you are having trouble with your device and your plan. I can certainly look into that for you.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "agent",
      "text": "Before we dive into the account details, could you please provide your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure, it is 92856959.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. And just to confirm, what is the phone number and email address associated with the account?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "The phone number is 99874 73445 and my email is emily.29@examplemail.com.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Perfect. Now, regarding the plan change, I can see your current options. I can move you to a higher data tier.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Great, please do that. Also, my screen keeps flickering on my device. Can you fix that remotely?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I cannot fix a hardware issue remotely, but I can check if your device is still under warranty.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I don't want to go to a store. I just want this sorted now. Why is this so difficult?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand your frustration, but there are certain steps we must follow for device repairs.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "This is ridiculous. I'm not getting any answers and you're not actually changing my plan right now!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am trying to process the request, but the system is currently unresponsive. I cannot complete the plan change at this moment.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Are you kidding me? I've wasted my time on this call and nothing is fixed. This is absolutely pathetic service!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I apologize for the inconvenience. Is there anything else I can assist you with today? I will have to ask you to call back later once the system is restored. Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
